struct P{double base,I0,T,bt,at;std::string bf,af;};
struct Crop{int first,maxday,maxyield;bool ongoing;};
static const std::unordered_map<std::string,P> DEF={{"WHEAT",{25,10000,400,.8,.2,"sqrt","log"}},{"CARROT",{35,10000,450,1,.7,"hinge","sqrt"}},{"TOMATO",{60,10000,200,.4,.6,"hinge","sqrt"}},{"STRAWBERRY",{120,10000,100,.7,1.6,"sqrt","linear"}},{"MELON",{250,10000,300,.2,3.6,"log","sq"}},{"EGG",{50,10000,332,.4,.2,"hinge","log"}},{"MILK",{160,10000,122,.6,1.6,"sqrt","linear"}},{"WOOL",{200,10000,105,.2,3.2,"log","sq"}},{"FERTILIZER",{100,10000,200,.4,.4,"linear","linear"}}};
