static int price(const P&p,double inv){double v;if(inv<p.I0){double den=shape(p.bf,p.T,p.T);v=p.base+(p.bt*p.base/den)*shape(p.bf,p.I0-inv,p.T);}else{double den=shape(p.af,p.T,p.T);v=p.base-(p.at*p.base/den)*shape(p.af,inv-p.I0,p.T);}return std::max(1,(int)std::nearbyint(v));}
static double quote_priority(py::dict obs,py::sequence order,py::dict stock){if(py::len(order)<3)return 0;std::string item=py::cast<std::string>(order[1]);if(!DEF.count(item))return 0;py::str key(item);int q=std::max(0,ai(order[2]));q=std::min(q,stock.contains(key)?std::max(0,ai(stock[key])):0);if(!q)return 0;auto market=py::cast<py::dict>(obs["market"]);auto invs=py::cast<py::dict>(market["inventory"]);int inv=ai(invs[key]);P p=params_for(item,market);int player=ai(obs["player"]);auto farms=py::cast<py::sequence>(obs["farms"]);auto rival=py::cast<py::dict>(farms[1-player]);auto tiles=py::cast<py::sequence>(rival["tiles"]);std::string crop,animal;if(CROPS.count(item))crop=item;else if(item=="EGG")animal="GOOSE";else if(item=="MILK")animal="COW";else if(item=="WOOL")animal="SHEEP";int standing=0;for(py::handle rh:tiles)for(py::handle th:py::cast<py::sequence>(rh)){if(!py::isinstance<py::dict>(th))continue;auto t=py::cast<py::dict>(th);bool match=false;if(!crop.empty()&&t.contains("crop")&&!t["crop"].is_none())match=py::cast<std::string>(t["crop"])==crop;else if(!animal.empty()&&t.contains("animal")&&!t["animal"].is_none())match=py::cast<std::string>(t["animal"])==animal;if(match&&t.contains("yield_units"))standing+=std::max(0,ai(t["yield_units"]));}int batch=std::min(24,std::max(8,standing));long long now=0,later=0;for(int j=0;j<q;++j){now+=price(p,inv+j);later+=price(p,inv+batch+j);}return(double)(now-later);}
static long long stock_total(py::dict d){long long s=0;for(auto kv:d)s+=all(kv.second);return s;}
static py::tuple market_stock(py::dict shed,py::sequence orders){py::dict stock=py::cast<py::dict>(clone_obj(shed)),buys,sales;for(ssize_t i=0;i<py::len(orders);++i){py::handle oh=orders[i];if(oh.is_none()||!PySequence_Check(oh.ptr()))continue;auto o=py::reinterpret_borrow<py::sequence>(oh);if(py::len(o)<3)continue;std::string op=py::cast<std::string>(o[0]);py::object item=py::reinterpret_borrow<py::object>(o[1]);long long n=std::max<long long>(0,all(o[2]));if(op=="SELL"){long long have=stock.contains(item)?std::max<long long>(0,all(stock[item])):0,q=std::min(n,have);stock[item]=have-q;sales[py::int_(i)]=q;}else if(op=="BUY_PRODUCT"||op=="BUY_ANIMAL"){long long q=std::min(n,std::max<long long>(0,100-stock_total(stock)));stock[item]=(stock.contains(item)?all(stock[item]):0)+q;buys[py::int_(i)]=q;}}return py::make_tuple(stock,buys,sales);}
static py::tuple delivery(py::dict original,py::dict priv,bool night){py::dict stock=py::cast<py::dict>(clone_obj(original)),lost;if(night&&priv.contains("inventories"))for(py::handle ih:py::cast<py::sequence>(priv["inventories"])){auto inv=py::cast<py::dict>(ih);for(auto kv:inv){long long q=std::max<long long>(0,all(kv.second)),take=std::min(q,std::max<long long>(0,100-stock_total(stock)));stock[kv.first]=(stock.contains(kv.first)?all(stock[kv.first]):0)+take;if(q>take)lost[kv.first]=(lost.contains(kv.first)?all(lost[kv.first]):0)+q-take;}}return py::make_tuple(stock,lost);}
static long long fib(int n){long long a=0,b=1;for(int i=0;i<n;++i){long long c=a+b;a=b;b=c;}return a;}
static bool budget(py::dict obs,py::sequence orders){int player=ai(obs["player"]);auto farms=py::cast<py::sequence>(obs["farms"]);auto farm=py::cast<py::dict>(farms[player]);int hires=ai(farm["hires_today"]);long long cost=0;auto market=py::cast<py::dict>(obs["market"]);auto inv=py::cast<py::dict>(market["inventory"]);int wheat=price(DEF.at("WHEAT"),all(inv["WHEAT"])-2000),fert=price(DEF.at("FERTILIZER"),all(inv["FERTILIZER"])-2000);for(py::handle oh:orders){if(oh.is_none()||!PySequence_Check(oh.ptr()))continue;auto o=py::reinterpret_borrow<py::sequence>(oh);if(!py::len(o))continue;std::string op=py::cast<std::string>(o[0]);if(op=="HIRE"){cost+=fib(hires);++hires;}else if(op=="BUY_LAND")cost+=4000;else if(py::len(o)>2){std::string item=py::cast<std::string>(o[1]);long long q=std::max<long long>(0,all(o[2]));if(op=="BUY_PRODUCT")cost+=q*(item=="WHEAT"?wheat:fert);else if(op=="BUY_ANIMAL")cost+=q*(item=="GOOSE"?300:item=="COW"?400:500);else if(op=="BUY_SEED")cost+=q*(item=="WHEAT"?10:item=="CARROT"?20:item=="TOMATO"?50:item=="STRAWBERRY"?100:80);}}return(double)cost<=ad(farm["money"]);}
static bool shed_adj(int x,int y,int board){int h=board/2;return(x==h-1||x==h)&&(y==h-1||y==h);}static std::pair<int,int> pos(py::dict farm,int idx){py::handle h=idx==0?farm["farmer"]:py::cast<py::sequence>(farm["hands"])[idx-1];auto p=py::cast<py::sequence>(h);return{ai(p[0]),ai(p[1])};}static void setpos(py::dict farm,int idx,int x,int y){py::list p;p.append(x);p.append(y);if(idx==0)farm["farmer"]=p;else{auto h=py::cast<py::list>(farm["hands"]);h[idx-1]=p;}}
