static py::tuple r127_fields(py::dict obs,py::dict action){int p=ai(obs["player"]),day=ai(obs["step"])/24;auto farms=py::cast<py::sequence>(obs["farms"]);auto farm=py::cast<py::dict>(clone_obj(farms[p]));auto priv=py::cast<py::dict>(clone_obj(obs["private"]));py::list cmds;cmds.append(action.contains("farmer")&&truthy(action["farmer"])?clone_obj(action["farmer"]):py::object(py::list(1)));if(!truthy(cmds[0])){py::list q;q.append("PASS");cmds[0]=q;}if(action.contains("hands")&&!action["hands"].is_none())for(py::handle c:py::cast<py::sequence>(action["hands"]))cmds.append(c);std::unordered_map<std::string,int>demand;for(py::handle ch:cmds){if(!PySequence_Check(ch.ptr()))continue;auto c=py::cast<py::sequence>(ch);if(py::len(c)>1&&py::cast<std::string>(c[0])=="PLANT")demand[py::cast<std::string>(c[1])]++;}auto seeds=py::cast<py::dict>(priv["seeds"]);auto invs=py::cast<py::sequence>(priv["inventories"]);int n=std::min((int)py::len(cmds),(int)py::len(invs));for(int i=0;i<n;++i){auto c=py::cast<py::sequence>(cmds[i]);if(py::len(c)>1&&py::cast<std::string>(c[0])=="PLANT"){std::string crop=py::cast<std::string>(c[1]);py::str k(crop);if(demand[crop]>(seeds.contains(k)?ai(seeds[k]):0))continue;}apply(farm,priv,i,cmds[i],10,day,24,100);}return py::make_tuple(farm,priv);}
